// New openings, places to watch, and closings. Read from data/openings.csv.
// Preview shows every row. The live site shows only rows marked verified, so nothing unchecked goes public.
import { readTable, byName, businesses, href, IS_PREVIEW } from './data';

export type Opening = {
  kind: 'open' | 'watch' | 'closed'; name: string; area: string; detail: string; date: string; dateNote: string;
  link: string; source: string; sourceUrl: string; checked: string; verified: boolean; profile: string;
};

const yes = (v: string) => /^(yes|true|verified)$/i.test((v || '').trim());
const all: Opening[] = readTable('openings.csv').filter((r) => r.name && r.kind).map((r) => ({
  kind: r.kind.toLowerCase() as Opening['kind'], name: r.name, area: r.area, detail: r.detail, date: r.date, dateNote: r.date_note,
  link: r.link, source: r.source, sourceUrl: r.source_url, checked: r.checked, verified: yes(r.verified), profile: r.profile,
}));
export const openings: Opening[] = all.filter((o) => IS_PREVIEW || o.verified);

const DAY = 86400000;
const stamp = (s: string) => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || ''); return m ? +new Date(+m[1], +m[2] - 1, +m[3]) : 0; };
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// Recent ones only: opened in the last 60 days, closed in the last 75, and upcoming places until two weeks after the date.
export function openingsOf(kind: Opening['kind'], today = new Date()) {
  const t0 = +new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const rows = openings.filter((o) => o.kind === kind);
  if (kind === 'open') return rows.filter((o) => !stamp(o.date) || stamp(o.date) >= t0 - 60 * DAY).sort((a, b) => stamp(b.date) - stamp(a.date));
  if (kind === 'closed') return rows.filter((o) => !stamp(o.date) || stamp(o.date) >= t0 - 75 * DAY).sort((a, b) => stamp(b.date) - stamp(a.date));
  return rows.filter((o) => !stamp(o.date) || stamp(o.date) >= t0 - 14 * DAY).sort((a, b) => (stamp(a.date) || 9e15) - (stamp(b.date) || 9e15));
}

export const whenText = (o: Opening) => {
  if (o.dateNote) return o.dateNote;
  const t = stamp(o.date); if (!t) return '';
  const d = new Date(t); return MONTHS[d.getMonth()] + ' ' + d.getDate();
};
// A page on this site, when the place is one we have a profile for.
export const profileHref = (o: Opening) => { const p = byName(o.profile || o.name); return p ? href(p) : ''; };
// Places we reviewed that the sheet marks closed.
export const closedReviewed = () => businesses().filter((b) => b.status === 'Closed').sort((a, b) => a.name.localeCompare(b.name));
export const lastChecked = () => {
  const t = stamp(openings.map((o) => o.checked).filter(Boolean).sort().slice(-1)[0] || '');
  if (!t) return '';
  const d = new Date(t); return MONTHS[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
};

__files.src/components/OpeningsPanel.astro:
---
import { openingsOf, whenText, profileHref } from '../lib/openings';
import { url } from '../lib/data';
const { limit = 3 } = Astro.props;
const groups = [
  { id: 'now-open', title: 'Now open', rows: openingsOf('open') },
  { id: 'places-to-watch', title: 'Places to watch', rows: openingsOf('watch') },
  { id: 'recently-closed', title: 'Recently closed', rows: openingsOf('closed') },
].filter((g) => g.rows.length > 0);
---
{groups.length > 0 && (
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px">
    {groups.map((g) => (
      <div class="card pad">
        <p class="eyebrow" style="margin-bottom:6px">{g.title}</p>
        {g.rows.slice(0, limit).map((o, i) => {
          const h = profileHref(o);
          return (
            <div class="row" style={i === 0 ? 'border-top:0;padding:12px 0' : 'padding:12px 0'}>
              <div style="flex:1;min-width:0">
                {h ? <a href={h} style="font-weight:700">{o.name}</a> : <b>{o.name}</b>}<br />
                <span class="meta" style="font-size:15px">{[o.area, whenText(o)].filter(Boolean).join(', ')}</span>
              </div>
            </div>
          );
        })}
        <p style="margin-top:12px"><a href={url('/openings-and-closings') + '#' + g.id} style="font-weight:700">{g.rows.length > limit ? 'See all ' + g.rows.length : 'See details'}</a></p>
      </div>
    ))}
  </div>
)}

__files.src/pages/openings-and-closings.astro:
---
import Base from '../layouts/Base.astro';
import '../styles/pages.css';
import { url, href, IS_PREVIEW } from '../lib/data';
import { openingsOf, whenText, profileHref, closedReviewed, lastChecked } from '../lib/openings';
const groups = [
  { id: 'now-open', eyebrow: 'Now open', title: 'Fresh on the list.', rows: openingsOf('open') },
  { id: 'places-to-watch', eyebrow: 'Places to watch', title: 'Coming soon.', rows: openingsOf('watch') },
  { id: 'recently-closed', eyebrow: 'Recently closed', title: 'Saying goodbye.', rows: openingsOf('closed') },
];
const gone = closedReviewed();
const any = groups.some((g) => g.rows.length > 0);
const checked = lastChecked();
const tip = 'mailto:traditionlocal@gmail.com?subject=Opening%20or%20closing%20tip';
---
<Base title="Openings and closings" active="Food" description="What just opened, what is on the way, and what Houston said goodbye to.">
  <section class="band hero">
    <div class="wrap">
      <p class="eyebrow">Openings and closings</p>
      <h1 style="margin-bottom:16px;max-width:900px">What is new in Houston food and drink.</h1>
      <p class="lead" style="max-width:720px">What just opened, what is on the way, and what we said goodbye to. Every tip shows where it came from.{checked && (' Last checked ' + checked + '.')}</p>
      {IS_PREVIEW && <p class="meta" style="margin-top:14px;max-width:720px">Preview note: items tagged Needs check stay hidden on the live site until they are marked verified.</p>}
    </div>
  </section>

  {!any && (
    <section class="band"><div class="wrap"><div class="card pad"><b>Nothing new to report yet.</b><p class="meta" style="margin-top:4px">Check back soon, or tell us about a place we should know.</p></div></div></section>
  )}

  {groups.filter((g) => g.rows.length > 0).map((g, gi) => (
    <section class={gi % 2 === 0 ? 'band' : 'band tint'} id={g.id}>
      <div class="wrap">
        <p class="eyebrow">{g.eyebrow}</p><h2 style="margin-bottom:28px">{g.title}</h2>
        <div class="grid g3">
          {g.rows.map((o) => {
            const h = profileHref(o);
            return (
              <div class="card pad">
                <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">
                  {whenText(o) && <span class="tag">{whenText(o)}</span>}
                  {o.area && <span class="tag soft">{o.area}</span>}
                  {IS_PREVIEW && !o.verified && <span class="tag soft">Needs check</span>}
                </div>
                <h4 style="margin-bottom:6px">{h ? <a href={h}>{o.name}</a> : o.link ? <a href={o.link} rel="noopener">{o.name}</a> : o.name}</h4>
                <p class="meta" style="font-size:15px;margin-bottom:10px">{o.detail}</p>
                {o.source && <p class="meta" style="font-size:13px">Source: {o.sourceUrl ? <a href={o.sourceUrl} rel="noopener">{o.source}</a> : o.source}</p>}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  ))}

  {gone.length > 0 && (
    <section class="band" id="reviewed-closed">
      <div class="wrap">
        <p class="eyebrow">From our reviews</p><h2 style="margin-bottom:8px">Places we reviewed that have closed.</h2>
        <p class="meta" style="font-size:17px;margin-bottom:24px;max-width:720px">{gone.length} places we have reviewed are marked closed in our latest check. Their reviews stay up as a record.</p>
        <div class="grid g3">{gone.map((b) => <a class="card pad" href={href(b)} style="text-decoration:none"><h4 style="margin-bottom:4px">{b.name}</h4><p class="meta">{b.area || 'Houston area'}</p></a>)}</div>
      </div>
    </section>
  )}

  <section class="band butter">
    <div class="wrap" style="display:flex;justify-content:space-between;align-items:center;gap:32px;flex-wrap:wrap">
      <div style="max-width:700px"><h3 style="margin-bottom:8px">Know about an opening or a closing?</h3><p style="font-size:17px">Send us a tip, and we will take a look.</p></div>
      <div style="display:flex;gap:12px;flex-wrap:wrap"><a class="btn" href={tip}>Send a tip</a><a class="btn line" href={url('/food')}>Explore Food</a></div>
    </div>
  </section>
</Base>

